+import { arguments_assert } from "./arguments_assert.mjs";
+import { list_permutations } from "./list_permutations.mjs";
+import { list_map } from "./list_map.mjs";
+import { reply_choice } from "./reply_choice.mjs";
+export function reply_any_order(pieces, rule_of) {
+  arguments_assert(arguments, 2);
+  ("Every one of the pieces, each exactly once, in whatever order the message happens to put them. rule_of is handed one ordering and makes the rule for it, so what goes back can follow the order the message spoke in. The orderings are written out rather than searched for, so the number of them grows as a factorial: keep the list small.");
+  let orderings = list_permutations(pieces);
+  let rules = list_map(orderings, rule_of);
+  let any_order = reply_choice(rules);
+  return any_order;
+}
